Untested: `escapeRegex`, `buildPattern`, `routeTask`.

Gaps:
- Word-boundary regression (the file's own header references a bug fix, #2257, for `cd`/`ci`/`add` matching inside `decision`/`infrastructure`/`address`) — no regression test locks this in.
- Multi-word phrase matching (`"unit test"`, `"ci/cd"`) vs. single-token matching.
- Pattern priority when a task matches multiple categories (e.g. "review the api tests" — reviewer should win because it's checked first).
- Default fallback path (`agent: 'coder'`, confidence `0.3`) when nothing matches.
- Non-string/null/undefined input (`routeTask(null)`, `routeTask(undefined)`) — relies on `String(task ?? '')`.
- Case-insensitivity and special-regex-character injection in the task string (e.g. task containing `(`, `.*`).

```js
// test/router.test.js
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { routeTask, buildPattern } = require('../.claude/helpers/router.js');

test('routes plain keyword to expected agent', () => {
  assert.equal(routeTask('please refactor this module').agent, 'coder');
});

test('#2257: short tokens do not match inside unrelated words', () => {
  assert.notEqual(routeTask('make a decision about scope').agent, 'devops'); // 'cd' in "decision"
  assert.notEqual(routeTask('update infrastructure docs').agent, 'coder');   // 'add' guard doesn't apply here, adjust per real word list
});

test('multi-word phrase matches with boundaries, not substring', () => {
  assert.equal(routeTask('set up ci/cd pipeline').agent, 'devops');
});

test('falls back to default coder route when nothing matches', () => {
  const r = routeTask('xyz completely unrelated gibberish qqq');
  assert.deepEqual(r, { agent: 'coder', confidence: 0.3, reason: 'Default routing - no specific keyword matched' });
});

test('handles null/undefined without throwing', () => {
  assert.doesNotThrow(() => routeTask(null));
  assert.doesNotThrow(() => routeTask(undefined));
});

test('buildPattern escapes regex metacharacters in tokens', () => {
  const re = buildPattern(['c++', 'a.b']);
  assert.ok(re.test('using c++ today'));
  assert.ok(!re.test('using cXXX today')); // '.' must not act as wildcard
});
```

Untested: `loadMemory`, `saveMemory`, `get`/`set`/`delete`/`clear`/`keys`.

Gaps:
- Corrupted JSON file in `loadMemory` — swallowed silently, returns `{}` (data-loss risk, no test verifies the fallback).
- `set`/`delete` with no `key` — logs error but doesn't throw; no test asserts memory is left unchanged.
- `keys()` must filter out `_`-prefixed internal fields (e.g. `_updated`) — no test.
- Concurrent `set` calls: `loadMemory` → mutate → `saveMemory` has no locking; two processes can race (last-write-wins, unlike `session.js`'s atomic rename pattern). No test documents/reproduces this.
- `saveMemory` doesn't use atomic write (unlike `session.js`) — a crash mid-`writeFileSync` can corrupt `memory.json`. Worth a test that at least documents current non-atomic behavior, or better, an actual fix ported from `session.js`.

```js
// test/memory.test.js
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const os = require('os');

function loadMemoryModuleInTmpCwd() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'mem-test-'));
  const prevCwd = process.cwd();
  process.chdir(dir);
  delete require.cache[require.resolve('../.claude/helpers/memory.js')];
  const mod = require('../.claude/helpers/memory.js');
  return { mod, dir, restore: () => process.chdir(prevCwd) };
}

test('set/get round-trip', () => {
  const { mod, restore } = loadMemoryModuleInTmpCwd();
  mod.set('foo', 'bar');
  assert.equal(mod.get('foo'), 'bar');
  restore();
});

test('corrupted memory.json falls back to empty object instead of throwing', () => {
  const { mod, dir, restore } = loadMemoryModuleInTmpCwd();
  const file = path.join(dir, '.claude-flow', 'data', 'memory.json');
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, '{ not valid json');
  assert.doesNotThrow(() => mod.get());
  assert.deepEqual(mod.get(), {});
  restore();
});

test('keys() excludes internal underscore-prefixed fields', () => {
  const { mod, restore } = loadMemoryModuleInTmpCwd();
  mod.set('a', '1');
  const keys = mod.keys();
  assert.ok(!keys.includes('_updated'));
  assert.ok(keys.includes('a'));
  restore();
});

test('set with missing key does not mutate store', () => {
  const { mod, restore } = loadMemoryModuleInTmpCwd();
  mod.set('a', '1');
  mod.set(undefined, 'x');
  assert.deepEqual(Object.keys(mod.get()).filter(k => !k.startsWith('_')), ['a']);
  restore();
});
```

Untested: `atomicWrite`, `start`/`restore`/`end`/`status`/`update`/`get`/`metric`.

Gaps:
- Corrupted `current.json` in `restore()` is handled (falls back to `commands.start()`), but `end()`, `status()`, `update()`, and `metric()` call `JSON.parse` **without** a try/catch — a corrupted session file will throw uncaught in those paths. This is a real, confirmed gap, not speculative.
- `atomicWrite` correctness under concurrent writers (the comment references bugs #2307/#1707/#1637) — no test proves rename-based atomicity or that a `.tmp.<pid>` file never leaks after a crash.
- `end()` when `session.startedAt` is missing/malformed → `NaN` duration.
- `metric(name)` for an unknown metric name silently no-ops (returns session unchanged) — should be asserted.
- `get(key)` when `session.context` is undefined (older session format) — falls back to `{}`, but only in `get`, not in `update` (`session.context[key] = value` would throw on a session written before `context` existed).

```js
// test/session.test.js
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const os = require('os');

function freshSessionModule() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sess-test-'));
  process.chdir(dir);
  delete require.cache[require.resolve('../.claude/helpers/session.js')];
  return require('../.claude/helpers/session.js');
}

test('start creates session with zeroed metrics', () => {
  const session = freshSessionModule();
  const s = session.start();
  assert.equal(s.metrics.edits, 0);
});

test('restore on corrupted file starts a fresh session instead of throwing', () => {
  const session = freshSessionModule();
  const file = path.join(process.cwd(), '.claude-flow', 'sessions', 'current.json');
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, '{ bad json');
  assert.doesNotThrow(() => session.restore());
});

test('BUG: status() throws (not caught) on corrupted session file', () => {
  const session = freshSessionModule();
  session.start();
  const file = path.join(process.cwd(), '.claude-flow', 'sessions', 'current.json');
  fs.writeFileSync(file, '{ bad json');
  assert.throws(() => session.status()); // documents current unguarded JSON.parse
});

test('metric() increments a known counter and no-ops for unknown name', () => {
  const session = freshSessionModule();
  session.start();
  const s1 = session.metric('edits');
  assert.equal(s1.metrics.edits, 1);
  const s2 = session.metric('not_a_real_metric');
  assert.equal(s2.metrics.edits, 1); // unchanged
});

test('end() archives session and removes current.json', () => {
  const session = freshSessionModule();
  const started = session.start();
  const ended = session.end();
  assert.equal(ended.id, started.id);
  const file = path.join(process.cwd(), '.claude-flow', 'sessions', 'current.json');
  assert.equal(fs.existsSync(file), false);
});
```

This is the highest-value target: it exists specifically to prevent command injection, but has **no test proving it actually does**.

Gaps:
- No test that a body containing `` ` ``, `$(...)`, `;`, or newlines is passed through untouched via `--body-file` rather than interpolated.
- `MAX_BODY_BYTES` boundary: exactly 256KB, 256KB+1, multi-byte UTF-8 (`Buffer.byteLength` vs `.length` mismatch for non-ASCII bodies).
- Temp file cleanup (`finally` block) when `execFileSync` throws — no test confirms the tmp file is unlinked on failure, not just success.
- `GITHUB_SAFE_DRY_RUN=1` path — no test asserts it exits 0 without ever invoking `gh`.
- `issue comment` positional-body form vs. `pr create --body` flag form — two different arg-parsing branches, both need coverage.
- Missing `--body` flag (`bodyIndex === -1`) with `create` subcommand — falls through to the "no body content" branch; should assert normal passthrough.

```js
// test/github-safe.test.js (spawn as subprocess since it's a script, not a module)
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { execFileSync } = require('child_process');

function run(args, env = {}) {
  return execFileSync('node', ['.claude/helpers/github-safe.js', ...args], {
    env: { ...process.env, GITHUB_SAFE_DRY_RUN: '1', ...env },
    encoding: 'utf8',
  });
}

test('injection payload in body is not shell-interpolated', () => {
  const out = run(['issue', 'comment', '123', 'hello `whoami` $(id) ; rm -rf /']);
  assert.match(out, /--body-file/);
  assert.doesNotMatch(out, /whoami/); // raw payload never appears in the exec'd argv line
});

test('rejects body over 256KB before writing any temp file', () => {
  const bigBody = 'a'.repeat(256 * 1024 + 1);
  assert.throws(() => run(['issue', 'comment', '123', bigBody]));
});

test('dry-run never shells out to gh', () => {
  const out = run(['pr', 'create', '--title', 't', '--body', 'safe body']);
  assert.match(out, /^\[DRY-RUN\]/);
});

test('multi-byte body near the byte cap is measured in bytes, not chars', () => {
  const body = '€'.repeat(90 * 1024); // 3 bytes/char in UTF-8, ~270KB > cap
  assert.throws(() => run(['issue', 'comment', '123', body]));
});
```

Untested: `safeRequire`, `runWithTimeout`, `readStdin`, snake_case/camelCase normalization, the full `main()` dispatch.

Gaps:
- `runWithTimeout`'s own doc comment admits a known limitation (sync blocking work in `intelligence.init()` can't actually be interrupted) — no test exercises the timeout-fires-first vs. work-finishes-first race.
- `readStdin` when `process.stdin.isTTY` is true vs. piped — both branches untested.
- Malformed JSON on stdin — silently ignored (`hookInput = {}`), no test.
- `toolInput`/`toolName` normalization between `camelCase` and `snake_case` keys — a real compatibility surface with no test.
- Global 5s safety timer calling `process.exit(0)` — untestable in-process without mocking `process.exit`/timers; should at least be covered via a subprocess test with a stub helper that hangs.

```js
// test/hook-handler.test.js (subprocess-level, since main() runs on require via CLI dispatch)
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('child_process');

function runHook(command, stdinObj) {
  return spawnSync('node', ['.claude/helpers/hook-handler.cjs', command], {
    input: JSON.stringify(stdinObj),
    encoding: 'utf8',
    timeout: 6000,
  });
}

test('normalizes snake_case tool_input/tool_name from stdin', () => {
  const r = runHook('route', { tool_input: { command: 'ls' }, tool_name: 'Bash' });
  assert.equal(r.status, 0);
});

test('malformed stdin JSON does not crash the handler', () => {
  const r = spawnSync('node', ['.claude/helpers/hook-handler.cjs', 'route'], {
    input: '{ not json', encoding: 'utf8', timeout: 6000,
  });
  assert.equal(r.status, 0);
});

test('exits within the 5s global safety timeout even under stdin stall', () => {
  const start = Date.now();
  const r = spawnSync('node', ['.claude/helpers/hook-handler.cjs', 'route'], {
    encoding: 'utf8', timeout: 6000,
  });
  assert.ok(Date.now() - start < 5500);
});
```

